#!/usr/bin/env bash
# s3-libknc-gate.sh: the S3 gate for libknc. The reference is what
# Intel-Phi-3120A's card/lib/knc/build.sh assembles: knc-mvex-gen codec,
# fastlanes and memcpy, generated by knc-mvex built from the stack's
# current source (into this repository's build directory), symbols
# prefixed ref_. The candidate is knc.c, written by tests/s3/knc-c-gen.c,
# and tests/s3/vpu_memcpy.c, compiled by this clang. tests/s3/knc-gate.c
# runs both on card CARD (default 0). See s3-gate.md.
#
#   scripts/s3-libknc-gate.sh [CARD]
#   LLVM_BIN   the clang to test (default: the series build's)
set -uo pipefail
. "$(cd "$(dirname "$0")" && pwd)/env.sh"
CARD="${1:-0}"
B="${LLVM_BIN:-$llvm_build/llvm/bin}"; S="$llvm_build/llvm/bin"; T="$llvm_root/tests/s3"
CFG=(--config="$llvm_root/config/knc.cfg" --sysroot="$llvm_build/sysroot" -O2)
AUDIT="$PHI_STACK_ROOT/host/target/debug/phi-isa-audit"
w="$llvm_build/s3/gate-libknc"; rm -rf "$w"; mkdir -p "$w/ref"

# the reference, from the stack's current generator
(cd "$PHI_STACK_ROOT/host" && CARGO_TARGET_DIR="$llvm_build/knc-mvex-target" cargo build -q --release -p knc-mvex --locked) || exit 1
GEN="$llvm_build/knc-mvex-target/release/knc-mvex-gen"
for k in codec fastlanes memcpy; do
    "$GEN" "$k" > "$w/ref/knc_$k.S" && "$S/clang" "${CFG[@]}" -c -o "$w/ref/knc_$k.o" "$w/ref/knc_$k.S" || exit 1
done
"$S/llvm-ar" rcs "$w/ref.a" "$w"/ref/*.o && "$S/llvm-objcopy" --prefix-symbols=ref_ "$w/ref.a"

# the candidate
cc -O2 -o "$w/knc-c-gen" "$T/knc-c-gen.c" && "$w/knc-c-gen" > "$w/knc.c" || exit 1
"$B/clang" "${CFG[@]}" -c -o "$w/knc.o" "$w/knc.c" || exit 1
"$B/clang" "${CFG[@]}" -c -o "$w/vpu_memcpy.o" "$T/vpu_memcpy.c" || exit 1
LLVM_OBJDUMP="$B/llvm-objdump" "$llvm_root/oracle/codegen-check.sh" "$w/knc.o" "$w/vpu_memcpy.o" || exit 1
# the same exported functions and tables as the library
"$S/llvm-nm" --defined-only -g "$w/ref.a" | awk 'NF == 3 { sub(/^ref_/, "", $3); print $3 }' | sort > "$w/ref.syms"
"$S/llvm-nm" --defined-only -g "$w/knc.o" "$w/vpu_memcpy.o" | awk 'NF == 3 { print $3 }' | sort > "$w/knc.syms"
if ! cmp -s "$w/ref.syms" "$w/knc.syms"; then echo "s3-libknc-gate: exported symbols differ:"; diff "$w/ref.syms" "$w/knc.syms" | head; exit 1; fi
echo "symbols: $(wc -l < "$w/knc.syms") exported, the same as libknc's"

# linked as the stack links libknc (knc-cc: static, not PIE): its dispatch
# tables are absolute .quad entries in .rodata, which a static-pie refuses
LINK=(--target=x86_64-unknown-linux-musl -march=knc --sysroot="$llvm_build/sysroot" -static -fuse-ld=lld -rtlib=compiler-rt -unwindlib=none)
"$S/clang" "${LINK[@]}" -o "$w/knc-gate" "$T/knc-gate.c" "$w/knc.o" "$w/vpu_memcpy.o" "$w/ref.a" || exit 1
"$AUDIT" "$w/knc-gate" | tail -1 | sed 's/^/audit: /'
"$AUDIT" "$w/knc-gate" | tail -1 | grep -q '^result: 0 illegal' || { echo "s3-libknc-gate: audit found illegal instructions"; exit 1; }
phi -c "$CARD" put "$w/knc-gate" /data/s3-knc-gate < /dev/null > /dev/null
phi -c "$CARD" run sh -c 'cd /data; chmod +x s3-knc-gate; ./s3-knc-gate; echo "exit $?"; rm -f s3-knc-gate' < /dev/null 2>&1 > "$w/card$CARD.txt"
grep -v '^b[0-9]\|^unpack\|^pack\|^fls\|^encode' "$w/card$CARD.txt"
grep -q '^knc-gate: PASS' "$w/card$CARD.txt" && grep -q '^exit 0' "$w/card$CARD.txt"
